from typing import List

class Solution:
    def cherryPickup(self, grid: List[List[int]]) -> int:
        # Step 1: Define the dimensions of the DP table
        n, m = len(grid), len(grid[0])
        
        # Initialize the DP table
        dp = [[[-float('inf')] * m for _ in range(m)] for _ in range(n)]
        
        # Base Case: Initialize the first row of the DP table
        dp[0][0][m-1] = grid[0][0] + grid[0][m-1]  # Robots start at (0, 0) and (0, m-1)

        # Recurrence Relation: Fill the DP table for subsequent rows
        for i in range(1, n):  # Start from the second row
            for j1 in range(m):  # Position of the first robot
                for j2 in range(m):  # Position of the second robot
                    max_cherries = 0
                    # Check all possible previous positions for both robots
                    for j1_prev in range(max(0, j1 - 1), min(m, j1 + 2)):  # j1 can move left, stay, or right
                        for j2_prev in range(max(0, j2 - 1), min(m, j2 + 2)):  # j2 can move left, stay, or right
                            cherries = dp[i - 1][j1_prev][j2_prev]  # Calculate from previous positions
                            if j1 == j2:  # If both robots are in the same cell
                                cherries += grid[i][j1]  # Collect cherries only once
                            else:
                                cherries += grid[i][j1] + grid[i][j2]  # Collect cherries from both cells
                            max_cherries = max(max_cherries, cherries)
                    dp[i][j1][j2] = max_cherries  # Store the maximum cherries collected

        # The answer is the maximum cherries collected by the two robots in the last row
        return max(max(dp[n-1][j1][j2] for j2 in range(m)) for j1 in range(m))
        
